import{_ as a,a as t,c as o,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · Lesson 119 A true story","description":"学习 过去完成时，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 119 A true story","description":"学习 过去完成时，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 过去完成时，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 118 What were you doing?","link":"/life/english/new-concept/book-1/unit-05/lesson-118"},"next":{"text":"第一册：英语初阶 · Lesson 120 It had already happened.","link":"/life/english/new-concept/book-1/unit-05/lesson-120"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 118 What were you doing?","link":"/life/english/new-concept/book-1/unit-05/lesson-118"},"next":{"text":"第一册：英语初阶 · Lesson 120 It had already happened.","link":"/life/english/new-concept/book-1/unit-05/lesson-120"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-05/lesson-119.md","filePath":"life/english/new-concept/book-1/unit-05/lesson-119.md"}'),n={name:"life/english/new-concept/book-1/unit-05/lesson-119.md"};function r(l,e,s,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="第一册-英语初阶-·-lesson-119-a-true-story" tabindex="-1">第一册：英语初阶 · Lesson 119 A true story <a class="header-anchor" href="#第一册-英语初阶-·-lesson-119-a-true-story" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 119 A true story&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元 5</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-120">配套课 Lesson 120</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>说明两个过去事件的先后 本课要掌握过去完成时，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>story</td><td>/ˈstɔːri/</td><td>n.</td><td>故事</td><td>a true story</td></tr><tr><td>thief</td><td>/θiːf/</td><td>n.</td><td>小偷</td><td>catch a thief</td></tr><tr><td>before</td><td>/bɪˈfɔː/</td><td>conj.</td><td>在……之前</td><td>before we arrived</td></tr><tr><td>already</td><td>/ɔːlˈredi/</td><td>adv.</td><td>已经</td><td>had already left</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>had already left — 在过去某时之前已经离开</li><li>by the time — 到……时为止</li></ul><h2 id="语法讲解-过去完成时" tabindex="-1">语法讲解：过去完成时 <a class="header-anchor" href="#语法讲解-过去完成时" aria-label="Permalink to &quot;语法讲解：过去完成时&quot;">​</a></h2><p>过去完成时由 had + 过去分词构成，表示相对于一个过去参照点更早发生的动作。需要有过去参照点，不能只因为动作很久以前就用 had done。By the time we arrived, the shop had closed 中到达是参照点，关门更早。时间顺序非常明确时一般过去时也可能足够，但本课用过去完成时突出先后。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>By the time we arrived, the museum had closed.</p></blockquote><p>我们到达时，博物馆已经关门了。</p><p>We arrived 给出过去参照点；had closed 表博物馆关门发生得更早。by the time 强调到达时已有结果。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>过去完成时必须相对于过去参照点；不要只因 yesterday 就任意加 had。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“By the time we arrived, the museum had closed.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>By the time we arrived, the museum had closed. She had saved the file before the computer stopped.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“说明两个过去事件的先后”写两至三句，再读给同伴听。至少使用一次过去完成时，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>We arrived 给出过去参照点；had closed 表博物馆关门发生得更早。by the time 强调到达时已有结果。 Had saved 表先完成保存，stopped 表随后电脑停止；before 显式说明事件顺序。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补助动词：The museum ___ closed before we arrived.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> had</p><p><strong>解析：</strong> 按本课规则判断：过去完成时由 had + 过去分词构成，表示相对于一个过去参照点更早发生的动作。需要有过去参照点，不能只因为动作很久以前就用 had done。By the time we arrived, the shop had closed 中到达是参照点，关门更早。时间顺序非常明确时一般过去时也可能足够，但本课用过去完成时突出先后。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“我们到达时，博物馆已经关门了。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> By the time we arrived, the museum had closed.</p><p><strong>解析：</strong> We arrived 给出过去参照点；had closed 表博物馆关门发生得更早。by the time 强调到达时已有结果。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：She had saved the file before the computer stopped.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 电脑停止运行前她已经保存了文件。</p><p><strong>解析：</strong> Had saved 表先完成保存，stopped 表随后电脑停止；before 显式说明事件顺序。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去完成时。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-118">上一课</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-120">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(n,[["render",r]]);export{u as __pageData,b as default};
